    from pssolver.io.checkpoint import read_checkpoint_json
    restart_metadata = read_checkpoint_json(Path(workflow_spec.restart_from) / 'checkpoint.json', operation='plane_checkpoint_import')
    if restart_metadata.get('format_kind') == 'engine_state':
