        if save_start_step > engine_header['completed_steps'] + steps:
            _reject_plane_restart('save_start_step must not exceed the absolute final step', reason='save_start_step_after_final_step', step=engine_header['completed_steps'], details={'save_start_step': save_start_step, 'absolute_final_step': engine_header['completed_steps'] + steps})

77.statement:
if is_restart and restart_kind != 'engine_state':
    try:
        restart_header = read_plane_checkpoint_header(workflow_spec.restart_from)
    except SimulationRestartError:
        raise
    except CheckpointError:
        raise
    except Exception as exc:
        _reject_plane_restart(str(exc) or 'Plane checkpoint preflight failed', reason='checkpoint_preflight_failed', details={'legacy_exception_type': type(exc).__name__}, exception=exc)
    restart_step = getattr(restart_header, 'completed_steps', 0)
    if restart_header.runtime_path is not execution.runtime_path:
        _reject_plane_restart('cross-runtime Plane checkpoint restart is unsupported', reason='runtime_path_mismatch', step=restart_step, details={'checkpoint_runtime_path': restart_header.runtime_path.value, 'target_runtime_path': execution.runtime_path.value})
    if restart_header.format_version == PLANE_LEGACY_WORKFLOW_CHECKPOINT_FORMAT_VERSION:
        _reject_plane_restart('legacy Plane checkpoint requires explicit identity upgrade', reason='legacy_identity_upgrade_required', step=restart_step)
    checkpoint_identity = restart_header.compatibility_identity
    if checkpoint_identity is None:
        _reject_plane_restart('checkpoint compatibility identity is missing', reason='compatibility_identity_missing', step=restart_step)
    checkpoint_forward = checkpoint_identity.forward_dynamics.to_metadata()['payload']
    checkpoint_run_spec = checkpoint_forward.get('run_spec_dynamics')
    target_run_spec = plane_run_spec_dynamics_identity(run_spec).to_metadata()
    if checkpoint_run_spec != target_run_spec:
        _reject_plane_restart('checkpoint forward dynamics does not match target', reason='forward_dynamics_mismatch', step=restart_step)
    checkpoint_lifting = checkpoint_forward.get('lifting_dynamics')
    if lifting_plan is None:
        target_lifting_plan_sha256 = None
    else:
        target_lifting_plan_sha256 = lifting_plan.canonical_sha256()
    if checkpoint_lifting is None:
        checkpoint_lifting_plan_sha256 = None
    elif isinstance(checkpoint_lifting, dict):
        lifting_identity = checkpoint_lifting.get('lifting')
        checkpoint_lifting_plan_sha256 = lifting_identity.get('plan_sha256') if isinstance(lifting_identity, dict) else None
    else:
        checkpoint_lifting_plan_sha256 = None
    if checkpoint_lifting_plan_sha256 != target_lifting_plan_sha256:
        _reject_plane_restart('checkpoint static lifting dynamics does not match target', reason='static_lifting_dynamics_mismatch', step=restart_step)
    if save_start_step > restart_header.completed_steps + steps:
        _reject_plane_restart('save_start_step must not exceed the absolute final step', reason='save_start_step_after_final_step', step=restart_step, details={'save_start_step': save_start_step, 'absolute_final_step': restart_header.completed_steps + steps})

